                  label="Effective Date"
                  type="date"
                  outlined
                  dense
                  :max="today"
                ></v-text-field>
              </v-card-text>
              <v-card-actions class="pa-4 pt-0">
                <v-btn text small @click="goBack">Cancel</v-btn>
                <v-spacer></v-spacer>
                <v-btn color="primary" small @click="openConfirmDialog">
                  <v-icon left small>mdi-check-decagram</v-icon>Apply
                </v-btn>
              </v-card-actions>
            </v-card>
          </div>
        </aside>
      </div>
    </template>

    <v-snackbar v-model="snackbar.show" :color="snackbar.color" top right :timeout="4000">
      {{ snackbar.text }}
      <template #action="{ attrs }">
        <v-btn text v-bind="attrs" @click="snackbar.show = false">Close</v-btn>
      </template>
    </v-snackbar>
  </div>
</template>

<script>
import generalMixin from "../../mixins/general";
import processQuestionnaire from "../../mixins/processQuestionnaire";

const PROFILE =
  "http://ihris.org/fhir/StructureDefinition/staffs-exchange-locations-profile";
const REVIEW_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/review-staff-exchange-location-profile";

// Maps a request's own status code to the base code of whichever timeline
// stage is currently pending a decision on it.
const STATUS_STAGE_MAP = {
  undersupervisorreview: "supervisor",
  underdistricthrreview: "districthr",
  underdistricthodreview: "districthod",
  // Parked mid-handshake - the exchange is still AT that stage,
  // just waiting on the counterpart reviewer to act.
  awaitingpartnersupervisor: "supervisor",
  awaitingpartnerdistricthr: "districthr",
  awaitingpartnerdistricthod: "districthod",
  underhrdirectorreview: "directorhr",
  underdepartmentaldirreview: "departmentaldir",
  underpsreview: "ps",
  psapproved: "districthodapply",
  hodapplied: "districthodapply",
};

export default {
  name: "HodApplyStaffExchangeLocation",
  mixins: [generalMixin, processQuestionnaire],
  props: ["queries"],

  data() {
    return {
      url: "http://ihris.org/fhir/Questionnaire/hod-apply-staff-exchange-location",
      fhir: {},
      profile: REVIEW_PROFILE,

      positionFieldDefs: [
        { key: "designation", label: "DESIGNATION", icon: "mdi-account-tie" },
        { key: "department", label: "DEPARTMENT", icon: "mdi-tag-outline" },
        { key: "facility", label: "FACILITY", icon: "mdi-hospital-building" },
        { key: "district", label: "DISTRICT", icon: "mdi-map-marker" },
      ],

      loading: true,
      error: null,
      isAuthorized: false,

      requestId: null,
      staffPractitionerId: null,
      // Resolved before checkAccess - the District HOD who may apply this
      // is the one covering the DESTINATION facility, which (per the swap
      // symmetry) is found via the PARTNER's own current department, not
      // my own - matching applyStaffExchangeLocationWorkflow.js exactly.
      partnerStaffId: null,

      myRequest: {
        id: null,
        staffName: "",
        partnerRef: null,
        partnerName: "",
        plannedTransferDate: null,
        transferReason: "",
        status: null,
        statusDisplay: "Pending",
        eventDate: null,
        currentPosition: {},
        destinationPosition: {},
      },
      partnerRequest: {
        id: null,
        plannedTransferDate: null,
        transferReason: "",
        status: null,
        statusDisplay: "Pending",
        eventDate: null,
        currentPosition: {},
        destinationPosition: {},
      },
      // "none"      — partner hasn't submitted a matching request at all
      // "cancelled" — the partner's latest request was cancelled
      // "no-active" — the partner's latest request settled without ever
      //               reaching (or past) psapproved/hodapplied
      // "found"     — the partner's latest request is psapproved or
      //               hodapplied - still an active, applicable exchange
      partnerRequestState: "none",

      myExistingReview: null,
      reviews: [],

      sameDistrictHR: null,
      sameDistrictHOD: null,

      form: {
        date: new Date().toISOString().substr(0, 10),
        comments: "",
        supervisor: {
          reference: null,
          display: "",
          position: "",
          facility: "",
          grade: "",
        },
        partnerSupervisor: {
          reference: null,
          display: "",
          position: "",
          facility: "",
          grade: "",
        },
      },
      formSubmitted: false,
      saving: false,
      confirmDialog: false,

      // ── Supervisor picker ──────────────────────────────────────────────
      supervisorDialog: false,
      supervisorTarget: "mine", // "mine" | "partner" - which form field is being filled
      supervisorItems: [],
      supervisorTotal: 0,
      loadingSupervisors: false,
      supervisorOptions: { page: 1, itemsPerPage: 10 },
      supFilter: { name: "", position: "", department: null },
      supDebounce: null,
      supFilterTreeOpen: false,
      supervisorHeaders: [
        { text: "Name", value: "name", sortable: false },
        { text: "Position", value: "position", sortable: false },
        { text: "Department", value: "department", sortable: false },
        { text: "Facility", value: "facility", sortable: false },
        { text: "Grade", value: "grade", sortable: false },
        { text: "Employment Category", value: "employmentCategory", sortable: false },
        { text: "", value: "_action", sortable: false, align: "center", width: 100 },
      ],
      departmentOptions: [],
      filterTree: {
        items: [],
        active: [],
        open: [],
        treeLookup: {},
        loading: false,
        displayValue: "",
      },

      snackbar: { show: false, text: "", color: "success" },
    };
  },

  computed: {
    initials() {
      if (!this.myRequest.staffName) return "?";
      return this.myRequest.staffName
        .split(" ")
        .filter(Boolean)
        .slice(0, 2)
        .map((n) => n[0].toUpperCase())
        .join("");
    },
    today() {
      return new Date().toISOString().substr(0, 10);
    },
    isCancelled() {
      return this.myRequest.status === "cancelled";
    },
    // Everything before psapproved is "not yet reached" (handled by the
    // generic !myTurn alert below); anything past psapproved without an
    // existing "applied" review is "already moved on without me acting" -
    // a defensive fallback, since myExistingReview normally covers the
    // "I already applied" case directly.
    isPastMyStage() {
      const preStages = [
        "pending",
        "undersupervisorreview",
          "awaitingpartnersupervisor",
        "underdistricthrreview",
          "awaitingpartnerdistricthr",
        "underdistricthodreview",
          "awaitingpartnerdistricthod",
        "underhrdirectorreview",
        "underdepartmentaldirreview",
        "underpsreview",
      ];
      return (
        !!this.myRequest.status &&
        this.myRequest.status !== "psapproved" &&
        !preStages.includes(this.myRequest.status) &&
        !this.isCancelled
      );
    },
    myTurn() {
      return (
        this.myRequest.status === "psapproved" &&
        this.partnerRequestState === "found" &&
        !this.myExistingReview &&
        !this.isCancelled &&
        !this.isPastMyStage
      );
    },

    districtStageBannerText() {
      if (this.sameDistrictHR === null || this.sameDistrictHOD === null) {
        return "Checking whether both staff members share the same District HR/HOD coverage…";
      }
      if (this.sameDistrictHR && this.sameDistrictHOD) {
        return "Same District HR and HOD coverage — District HR and District HOD review both requests in one combined action.";
      }
      if (!this.sameDistrictHR && !this.sameDistrictHOD) {
        return "Different District HR and HOD coverage — each staff member is reviewed independently at the District HR and HOD stages.";
      }
      return `District HR review is ${this.sameDistrictHR ? "combined" : "independent per staff member"}; District HOD review is ${this.sameDistrictHOD ? "combined" : "independent per staff member"} — their facility coverage differs at only one of the two stages.`;
    },

    // sameDistrictHOD is reused here for the Apply stage's own combined-vs-
    // independent decision - see the matching comment in timeline() for why
    // that's mathematically the same determination as the destination-based
    // check applyStaffExchangeLocationWorkflow.js's own sharedReviewer does.
    applyBannerText() {
      if (this.sameDistrictHOD === null) {
        return "Checking whether you cover both destination facilities…";
      }
      if (this.sameDistrictHOD) {
        return "You cover both destination facilities — specify a new supervisor for each staff member below. Submitting finalizes both moves in one action.";
      }
      if (this.partnerRequest.status === "hodapplied") {
        return `${this.myRequest.partnerName || "The exchange partner"}'s own District HOD has already applied their half — submitting this will complete both moves now.`;
      }
      return `You are finalizing ${this.myRequest.staffName || "this staff member"}'s move only. ${this.myRequest.partnerName || "The exchange partner"}'s move will be finalized independently by their own District HOD.`;
    },

    timeline() {
      const findReview = (code, requestId) =>
        this.reviews.find(
          (r) =>
            r.reviewerCode === code &&
            r.requestId === requestId &&
            r.status !== "applied",
        ) || null;
      // The Apply stage reuses the SAME reviewer code ("districthod") as
      // the District HOD review stage earlier in the pipeline - it's
      // genuinely the same reviewer, just a different action, so review-
      // status ("applied" vs approved/rejected) is what distinguishes the
      // two, not the reviewer code.
      const findAppliedReview = (requestId) =>
        this.reviews.find(
          (r) =>
            r.reviewerCode === "districthod" &&
            r.requestId === requestId &&
            r.status === "applied",
        ) || null;

      const stages = [
        {
          code: "supervisor-mine",
          label: `Supervisor of ${this.myRequest.staffName || "This staff member"}`,
          review: findReview("supervisor", this.myRequest.id),
        },
        {
          code: "supervisor-partner",
          label: `Supervisor of ${this.myRequest.partnerName || "Exchange partner"}`,
          review: findReview("supervisor", this.partnerRequest.id),
        },
      ];

      const districtStages = [
        { code: "districthr", label: "District HR", combined: this.sameDistrictHR },
        { code: "districthod", label: "District HOD", combined: this.sameDistrictHOD },
      ];

      for (const stage of districtStages) {
        if (stage.combined) {
          stages.push({
            code: stage.code,
            label: `${stage.label} — Combined Review`,
            review: findReview(stage.code, this.myRequest.id),
          });
        } else {
          stages.push({
            code: stage.code + "-mine",
            label: `${stage.label} of ${this.myRequest.staffName || "This staff member"}`,
            review: findReview(stage.code, this.myRequest.id),
          });
          stages.push({
            code: stage.code + "-partner",
            label: `${stage.label} of ${this.myRequest.partnerName || "Exchange partner"}`,
            review: findReview(stage.code, this.partnerRequest.id),
          });
        }
      }

      const combinedStages = [
        { code: "directorhr", label: "HR Director" },
        { code: "departmentaldir", label: "Departmental Director" },
        { code: "ps", label: "PS" },
      ];
      for (const stage of combinedStages) {
        stages.push({
          code: stage.code,
          label: `${stage.label} — Combined Review`,
          review: findReview(stage.code, this.myRequest.id),
        });
      }

      // District HOD Apply - the finalization step after PS approval.
      // Combined-vs-independent here is mathematically the SAME
      // determination as sameDistrictHOD above: the backend's own
      // sharedReviewer check for this stage compares whether the same HOD
      // covers each staff's DESTINATION facility, but a swap only ever
      // involves this exact pair of facilities (my destination = partner's
      // origin, and vice versa) - "do the destinations share an HOD" and
      // "do the origins share an HOD" are the same boolean either way, so
      // sameDistrictHOD is reused directly rather than resolving it again.
      if (this.sameDistrictHOD) {
        stages.push({
          code: "districthodapply",
          label: "District HOD — Apply Transfer (Combined)",
          review: findAppliedReview(this.myRequest.id),
        });
      } else {
        stages.push({
          code: "districthodapply-mine",
          label: `District HOD — Apply Transfer of ${this.myRequest.staffName || "This staff member"}`,
          review: findAppliedReview(this.myRequest.id),
        });
        stages.push({
          code: "districthodapply-partner",
          label: `District HOD — Apply Transfer of ${this.myRequest.partnerName || "Exchange partner"}`,
          review: findAppliedReview(this.partnerRequest.id),
        });
      }

      return stages;
    },

    myCurrentStageCode() {
      return STATUS_STAGE_MAP[this.myRequest.status] || null;
    },
    partnerCurrentStageCode() {
      return STATUS_STAGE_MAP[this.partnerRequest.status] || null;
    },
  },

  watch: {
    // :options.sync on the supervisor picker's v-data-table updates this
    // (page, itemsPerPage, sort) whenever the user changes page - without
    // this watcher, that sync is silent and the table keeps showing
    // whichever page was last fetched.
    supervisorOptions: {
      handler() {
        if (this.supervisorDialog) this.fetchSupervisors();
      },
      deep: true,
    },
  },

  async created() {
    this.requestId = this.queries?.request;
    this.staffPractitionerId = this.queries?.practitioner;

    if (!this.requestId || !this.staffPractitionerId) {
      this.error = "No exchange request specified.";
      this.loading = false;
      return;
    }

    // partnerStaffId has to be known BEFORE authorization can be checked
    // (see checkAccess) - a lightweight first read just for that reference.
    try {
      const response = await fetch(`/fhir/Basic/${this.requestId}`);
      if (!response.ok) throw new Error("Exchange request not found");
      const resource = await response.json();
      if (!resource.meta?.profile?.includes(PROFILE)) {
        throw new Error("Resource is not a staff exchange request");
      }
      const partnerRef = this.getExt(resource, "staff-exchanging-with")
        ?.valueReference?.reference;
      this.partnerStaffId = this.refId(partnerRef);
    } catch (err) {
      console.error("Error resolving exchange partner:", err);
      this.error = err.message || "Failed to load exchange request details";
      this.loading = false;
      return;
    }

    await this.checkAccess();
    if (!this.isAuthorized) {
      this.loading = false;
      return;
    }

    await this.loadAll();
    await Promise.all([this.loadValueSets(), this.loadFilterTree()]);
  },

  methods: {
    // District HOD is a department/district/facility-scoped role - but the
    // one authorized to APPLY is whoever covers the DESTINATION facility,
    // which (by the swap symmetry) is found via the PARTNER's own current
    // department, not mine. /site/general/getHOD/:practitioner resolves
    // that staff's own department/district/facility server-side, so
    // passing partnerStaffId here is what makes this check match
    // applyStaffExchangeLocationWorkflow.js's own authorization exactly.
    async checkAccess() {
      try {
        await new Promise((resolve) => {
          if (!this.loadingUserData) {
            resolve();
            return;
          }
          const unwatch = this.$watch("loadingUserData", (newValue) => {
            if (!newValue) {
              unwatch();
              resolve();
            }
          });
          setTimeout(() => {
            unwatch();
            resolve();
          }, 15000);
        });

        const res = await fetch(`/site/general/getHOD/${this.partnerStaffId}`);
        if (!res.ok) {
          this.isAuthorized = false;
          return;
        }
        const data = await res.json();
        const hods = Array.isArray(data) ? data : [];
        this.isAuthorized = hods.some((hod) =>
          (hod.practitioners || []).some(
            (p) => String(p) === String(this.loggedInStaff.practitioner),
          ),
        );
      } catch (err) {
        console.error("checkAccess error:", err);
        this.isAuthorized = false;
      }
    },

    getExt(resource, urlParts) {
      const candidates = Array.isArray(urlParts) ? urlParts : [urlParts];
      const exts = resource.extension || [];
      for (const part of candidates) {
        const found = exts.find((e) => e.url.includes(part));
        if (found) return found;
      }
      return null;
    },

    async loadAll() {
      this.loading = true;
      this.error = null;
      try {
        const response = await fetch(`/fhir/Basic/${this.requestId}`);
        if (!response.ok) throw new Error("Exchange request not found");
        const resource = await response.json();
        if (!resource.meta?.profile?.includes(PROFILE)) {
          throw new Error("Resource is not a staff exchange request");
        }

        const requesterRef = this.getExt(resource, [
          "ihris-practitioner-reference",
          "practitioner",
        ])?.valueReference?.reference;
        const partnerRef = this.getExt(resource, "staff-exchanging-with")
          ?.valueReference?.reference;
        const statusCoding = this.getExt(resource, ["request-status", "status"])
          ?.valueCoding;
        const curExt = this.getExt(resource, [
          "position-reference",
          "current-position",
        ]);
        const destExt = this.getExt(resource, [
          "destination-position",
          "destition-position",
        ]);

        this.myRequest.id = resource.id;
        this.myRequest.partnerRef = partnerRef;
        this.myRequest.plannedTransferDate = this.getExt(
          resource,
          "planned-transfer-date",
        )?.valueDate;
        this.myRequest.transferReason = this.getExt(resource, [
          "reason",
          "transfer-reason",
        ])?.valueString;
        this.myRequest.status = statusCoding?.code || null;
        this.myRequest.statusDisplay = statusCoding?.display || "Pending";
        this.myRequest.eventDate =
          this.getExt(resource, "event-date")?.valueDate ||
          resource.meta?.lastUpdated;

        await Promise.all([
          this.loadPractitionerName(requesterRef, "myRequest", "staffName"),
          this.loadPractitionerName(partnerRef, "myRequest", "partnerName"),
          this.loadPosition(
            curExt?.valueReference?.reference,
            this.myRequest.currentPosition,
            curExt?.valueReference?.display,
          ).then((p) => (this.myRequest.currentPosition = p)),
          this.loadPosition(
            destExt?.valueReference?.reference,
            this.myRequest.destinationPosition,
            destExt?.valueReference?.display,
          ).then((p) => (this.myRequest.destinationPosition = p)),
          this.loadPartnerRequest(partnerRef),
          this.loadMyExistingReview(),
        ]);

        await this.loadReviews();

        if (this.partnerRequest.id) {
          await Promise.all([
            this.resolveSharedReviewer("HR").then(
              (shared) => (this.sameDistrictHR = shared),
            ),
            this.resolveSharedReviewer("HOD").then(
              (shared) => (this.sameDistrictHOD = shared),
            ),
          ]);
        }
      } catch (err) {
        console.error("Error loading exchange request:", err);
        this.error = err.message || "Failed to load exchange request details";
      } finally {
        this.loading = false;
      }
    },

    async loadReviews() {
      try {
        const wantedIds = [this.myRequest.id, this.partnerRequest.id].filter(
          Boolean,
        );
        if (!wantedIds.length) return;

        const res = await fetch(
          `/fhir/Basic?_profile=${REVIEW_PROFILE}&_count=200`,
        );
        const bundle = await res.json();
        const resources = (bundle.entry || []).map((e) => e.resource);

        const matches = [];
        for (const r of resources) {
          const refs = (r.extension || [])
            .filter((e) => e.url.includes("staff-exchange-location-reference"))
            .map((e) => e.valueReference?.reference);
          const requestId = wantedIds
            .map((id) => "Basic/" + id)
            .find((ref) => refs.includes(ref));
          if (!requestId) continue;
          matches.push({ resource: r, requestId: this.refId(requestId) });
        }

        const reviewerRefs = [
          ...new Set(
            matches
              .map(
                (m) =>
                  this.getExt(m.resource, [
                    "ihris-practitioner-reference",
                    "practitioner",
                  ])?.valueReference?.reference,
              )
              .filter(Boolean),
          ),
        ];
        const nameMap = {};
        await Promise.all(
          reviewerRefs.map(async (ref) => {
            try {
              const r = await fetch(`/fhir/${ref}?_elements=name`);
              const pract = await r.json();
              const name = pract.name?.[0];
              nameMap[ref] = name
                ? `${(name.given || []).join(" ")} ${name.family || ""}`.trim()
                : ref;
            } catch {
              nameMap[ref] = ref;
            }
          }),
        );

        this.reviews = matches.map(({ resource: r, requestId }) => {
          const reviewerRef = this.getExt(r, [
            "ihris-practitioner-reference",
            "practitioner",
          ])?.valueReference?.reference;
          const statusCoding = this.getExt(r, ["review-status", "status"])
            ?.valueCoding;
          return {
            id: r.id,
            requestId,
            reviewerCode: this.getExt(r, "reviewer")?.valueCoding?.code,
            reviewerName: nameMap[reviewerRef] || "Unknown",
            status: statusCoding?.code || null,
            statusDisplay: statusCoding?.display || "Pending",
            comments: this.getExt(r, "comments")?.valueString || "",
            date: this.getExt(r, ["date", "review-date"])?.valueDate,
          };
        });
      } catch (err) {
        console.error("loadReviews error:", err);
      }
    },

    // Same latest-request lookup as every other stage, but "found" now
    // means psapproved OR hodapplied - both are active, applicable states
    // at this point in the pipeline (matches applyStaffExchangeLocation-
    // Workflow.js's own partner-status check exactly).
    async loadPartnerRequest(partnerRef) {
      if (!partnerRef) return;
      try {
        const params = new URLSearchParams({
          _profile: PROFILE,
          practitioner: partnerRef,
          staffexchanginglocation: "Practitioner/" + this.staffPractitionerId,
          _sort: "-eventdate",
          _count: 1,
        });
        const res = await fetch(`/fhir/Basic?${params}`);
        const bundle = await res.json();
        const resource = bundle.entry?.[0]?.resource;

        if (!resource) {
          this.partnerRequestState = "none";
          return;
        }

        const statusCoding = this.getExt(resource, ["request-status", "status"])
          ?.valueCoding;
        const latestStatus = statusCoding?.code;

        if (latestStatus === "psapproved" || latestStatus === "hodapplied") {
          this.partnerRequestState = "found";
        } else if (latestStatus === "cancelled") {
          this.partnerRequestState = "cancelled";
        } else {
          this.partnerRequestState = "no-active";
        }

        const curExt = this.getExt(resource, [
          "position-reference",
          "current-position",
        ]);
        const destExt = this.getExt(resource, [
          "destination-position",
          "destition-position",
        ]);

        this.partnerRequest.id = resource.id;
        this.partnerRequest.plannedTransferDate = this.getExt(
          resource,
          "planned-transfer-date",
        )?.valueDate;
        this.partnerRequest.transferReason = this.getExt(resource, [
          "reason",
          "transfer-reason",
        ])?.valueString;
        this.partnerRequest.status = statusCoding?.code || null;
        this.partnerRequest.statusDisplay = statusCoding?.display || "Pending";
        this.partnerRequest.eventDate =
          this.getExt(resource, "event-date")?.valueDate ||
          resource.meta?.lastUpdated;

        const [curPos, destPos] = await Promise.all([
          this.loadPosition(
            curExt?.valueReference?.reference,
            {},
            curExt?.valueReference?.display,
          ),
          this.loadPosition(
            destExt?.valueReference?.reference,
            {},
            destExt?.valueReference?.display,
          ),
        ]);
        this.partnerRequest.currentPosition = curPos;
        this.partnerRequest.destinationPosition = destPos;
      } catch (err) {
        console.error("loadPartnerRequest error:", err);
      }
    },

    async resolveSharedReviewer(kind) {
      const mine = this.myRequest.currentPosition;
      const theirs = this.partnerRequest.currentPosition;
      if (!mine?.facilityId || !mine?.districtId) return null;
      if (!theirs?.facilityId || !theirs?.districtId) return null;

      const endpoint = kind === "HOD" ? "getHOD" : "getHR";
      const buildParams = (pos) => {
        const params = new URLSearchParams({
          district: pos.districtId,
          facility: pos.facilityId,
        });
        if (kind === "HOD") params.set("department", pos.departmentCode || "");
        return params;
      };

      try {
        const [resA, resB] = await Promise.all([
          fetch(`/site/general/${endpoint}?${buildParams(mine)}`),
          fetch(`/site/general/${endpoint}?${buildParams(theirs)}`),
        ]);
        if (!resA.ok || !resB.ok) return null;
        const [dataA, dataB] = await Promise.all([resA.json(), resB.json()]);
        const practitionersA = (Array.isArray(dataA) ? dataA : []).flatMap(
          (h) => h.practitioners || [],
        );
        const practitionersB = (Array.isArray(dataB) ? dataB : []).flatMap(
          (h) => h.practitioners || [],
        );
        return practitionersA.some((p) => practitionersB.includes(p));
      } catch (error) {
        console.error(`Error resolving shared ${kind}:`, error);
        return null;
      }
    },

    // Checks whether this District HOD has already applied this specific
    // request - filters on reviewer "districthod" AND status "applied"
    // specifically, so the original review-stage decision (same reviewer
    // code, different status) is never mistaken for an existing apply.
    async loadMyExistingReview() {
      try {
        const res = await fetch(
          `/fhir/Basic?_profile=${REVIEW_PROFILE}&_count=200`,
        );
        const bundle = await res.json();
        const resources = (bundle.entry || []).map((e) => e.resource);
        const mine = resources.find((r) => {
          const reviewerCode = this.getExt(r, "reviewer")?.valueCoding?.code;
          if (reviewerCode !== "districthod") return false;
          const statusCode = this.getExt(r, ["review-status", "status"])
            ?.valueCoding?.code;
          if (statusCode !== "applied") return false;
          const refs = (r.extension || []).filter((e) =>
            e.url.includes("staff-exchange-location-reference"),
          );
          return refs.some(
            (e) => e.valueReference?.reference === "Basic/" + this.requestId,
          );
        });
        if (mine) {
          this.myExistingReview = {
            date: this.getExt(mine, ["date", "review-date"])?.valueDate,
            comments: this.getExt(mine, "comments")?.valueString || "",
          };
        }
      } catch (err) {
        console.error("loadMyExistingReview error:", err);
      }
    },

    async loadPractitionerName(ref, target, field) {
      if (!ref) return;
      try {
        const id = ref.split("/")[1];
        const response = await fetch(`/fhir/Practitioner/${id}?_elements=name`);
        const practitioner = await response.json();
        const name = practitioner.name?.[0];
        this[target][field] = name
          ? `${(name.given || []).join(" ")} ${name.family || ""}`.trim()
          : "Unknown";
      } catch (error) {
        console.error("Error loading practitioner:", error);
        this[target][field] = "Unknown";
      }
    },

    refId(ref) {
      if (!ref) return null;
      return ref.includes("/") ? ref.split("/")[1] : ref;
    },

    async resolveDistrict(facilityRef) {
      try {
        let ref = facilityRef;
        for (let i = 0; i < 5 && ref; i++) {
          const id = this.refId(ref);
          if (!id) return { name: "", id: null };
          const res = await fetch(`/fhir/Location/${id}`);
          if (!res.ok) return { name: "", id: null };
          const loc = await res.json();
          if (loc.meta?.profile?.some((p) => p.includes("ls-district"))) {
            return { name: loc.name || "", id: loc.id };
          }
          ref = loc.partOf?.reference;
        }
        return { name: "", id: null };
      } catch (error) {
        console.error("Error resolving district:", error);
        return { name: "", id: null };
      }
    },

    async loadPosition(ref, seed, fallbackDisplay) {
      let result = { designation: fallbackDisplay || "", loadError: null, ...seed };
      if (!ref) return result;
      try {
        const id = this.refId(ref);
        if (!id) return result;
        const response = await fetch(`/fhir/Basic/${id}`);
        if (!response.ok) {
          return { ...result, loadError: `Could not load position (HTTP ${response.status})` };
        }
        const position = await response.json();
        const getExt = (part, type) => {
          const ext = position.extension?.find((e) => e.url.includes(part));
          return ext ? ext[type] : null;
        };

        let designation = fallbackDisplay || "";
        const designationRef = getExt("designation", "valueReference")?.reference;
        if (designationRef) {
          try {
            const dId = this.refId(designationRef);
            const dRes = await fetch(`/fhir/Basic/${dId}`);
            const dData = await dRes.json();
            designation =
              dData.extension?.find((e) => e.url.includes("ihris-basic-name"))
                ?.valueString || designation;
          } catch {
            // designation lookup best-effort
          }
        }

        let facility = "";
        let district = "";
        let districtId = null;
        let facilityId = null;
        const facilityRef = getExt("facility", "valueReference")?.reference;
        if (facilityRef) {
          facilityId = this.refId(facilityRef);
          try {
            const fRes = await fetch(`/fhir/Location/${facilityId}`);
            const fData = await fRes.json();
            facility = fData.name || "";
          } catch {
            // facility lookup best-effort
          }
          const resolved = await this.resolveDistrict(facilityRef);
          district = resolved.name;
          districtId = resolved.id;
        }

        return {
          designation,
          department: getExt("department", "valueCoding")?.display || "",
          departmentCode: getExt("department", "valueCoding")?.code || null,
          facility,
          facilityId,
          district,
          districtId,
        };
      } catch (error) {
        console.error("Error loading position:", error);
        return result;
      }
    },

    isCurrentStage(stage) {
      if (stage.code.endsWith("-mine")) {
        const base = stage.code.slice(0, -"-mine".length);
        return this.myCurrentStageCode === base;
      }
      if (stage.code.endsWith("-partner")) {
        const base = stage.code.slice(0, -"-partner".length);
        return this.partnerCurrentStageCode === base;
      }
      return this.myCurrentStageCode === stage.code;
    },

    statusKey(status) {
      if (!status) return "warn";
      if (status === "approved" || status === "completed") return "done";
      if (status && status.includes("rejected")) return "error";
      if (status === "cancelled") return "none";
      if (
        status &&
        (status.includes("review") ||
          status === "pending" ||
          status === "psapproved" ||
          status === "hodapplied" ||
          status === "applied")
      )
        return "active";
      return "warn";
    },

    formatDate(dateString) {
      if (!dateString) return "N/A";
      const date = new Date(dateString);
      if (isNaN(date.getTime())) return "N/A";
      const day = String(date.getDate()).padStart(2, "0");
      const month = String(date.getMonth() + 1).padStart(2, "0");
      return `${day}/${month}/${date.getFullYear()}`;
    },

    showSnackbar(text, color) {
      this.snackbar = { show: true, text, color: color || "success" };
    },

    goBack() {
      if (window.history.length > 1) {
        this.$router.go(-1);
      } else {
        this.$router.push("/");
      }
    },

    getInitials(name) {
      if (!name) return "?";
      return name
        .split(" ")
        .filter(Boolean)
        .slice(0, 2)
        .map((n) => n[0].toUpperCase())
        .join("");
    },

    async loadValueSets() {
      try {
        const dept = await this.$fhirutils.expand(
          "http://ihris.org/fhir/ValueSet/departments-valueset",
        );
        this.departmentOptions = (dept || []).map((c) => ({
          system: c.system,
          code: c.code,
          display: c.display,
        }));
      } catch (err) {
        console.error("loadValueSets error", err);
      }
    },

    // ── Supervisor picker ──────────────────────────────────────────────
    openSupervisorDialog(target) {
      this.supervisorTarget = target;
      this.supervisorDialog = true;
      this.fetchSupervisors();
    },

    debouncedFetchSupervisors() {
      clearTimeout(this.supDebounce);
      this.supDebounce = setTimeout(() => {
        this.supervisorOptions.page = 1;
        this.fetchSupervisors();
      }, 350);
    },

    async fetchSupervisors() {
      this.loadingSupervisors = true;
      try {
        const params = new URLSearchParams({
          page: this.supervisorOptions.page,
          count: this.supervisorOptions.itemsPerPage,
        });
        if (this.supFilter.name) params.set("name", this.supFilter.name);
        if (this.supFilter.position) params.set("position", this.supFilter.position);
        if (this.supFilter.department) params.set("department", this.supFilter.department);
        if (this.filterTree.active.length) {
          const id = this.filterTree.active[0];
          const info = this.filterTree.treeLookup[id];
          const locationId = id.split("/")[1];
          if (info?.type === "facility") params.set("facilityId", locationId);
          else if (info?.type === "council") params.set("councilId", locationId);
          else params.set("districtId", locationId);
        }

        const res = await fetch(`/site/position/supervisors?${params}`);
        const data = await res.json();

        this.supervisorTotal = data.total || 0;
        this.supervisorItems = data.supervisors || [];
      } catch (err) {
        console.error("fetchSupervisors error", err);
      } finally {
        this.loadingSupervisors = false;
      }
    },

    selectSupervisor(item) {
      const value = {
        reference: item.practitionerRef,
        display: item.name,
        position: item.position,
        facility: item.facility,
        grade: item.grade,
      };
      if (this.supervisorTarget === "partner") {
        this.form.partnerSupervisor = value;
      } else {
        this.form.supervisor = value;
      }
      this.supervisorDialog = false;
    },

    clearSupervisor(target) {
      const empty = { reference: null, display: "", position: "", facility: "", grade: "" };
      if (target === "partner") {
        this.form.partnerSupervisor = empty;
      } else {
        this.form.supervisor = empty;
      }
    },

    async loadFilterTree() {
      if (this.filterTree.items.length) return;
      this.filterTree.loading = true;
      try {
        const res = await fetch(
          "/fhir/Location?_profile=http://ihris.org/fhir/StructureDefinition/ls-district&partof=Location/countryls&_count=200",
        );
        const data = await res.json();
        const nodes = (data.entry || []).map((e) => ({
          id: "Location/" + e.resource.id,
          name: e.resource.name,
          children: [],
        }));
        nodes.forEach((n) => {
          this.filterTree.treeLookup[n.id] = { name: n.name, type: "district" };
        });
        this.filterTree.items = nodes;
      } catch (err) {
        console.error("loadFilterTree error", err);
      } finally {
        this.filterTree.loading = false;
      }
    },

    fetchFilterChildren(item) {
      const parentInfo = this.filterTree.treeLookup[item.id];
      const childType = parentInfo?.type === "district" ? "council" : "facility";
      return fetch(`/fhir/Location?partof=${item.id}&_count=200`)
        .then((r) => r.json())
        .then((data) => {
          const children = (data.entry || []).map((e) => {
            const node = { id: "Location/" + e.resource.id, name: e.resource.name };
            if (childType === "council") node.children = [];
            this.filterTree.treeLookup[node.id] = { name: node.name, type: childType };
            return node;
          });
          item.children.push(...children);
        })
        .catch((err) => console.error("fetchFilterChildren error", err));
    },

    clearFilterTree() {
      this.filterTree.active = [];
      this.filterTree.displayValue = "";
    },

    openConfirmDialog() {
      this.formSubmitted = true;
      if (!this.form.supervisor.reference) {
        this.showSnackbar("Please select the new supervisor.", "error");
        return;
      }
      if (this.sameDistrictHOD && !this.form.partnerSupervisor.reference) {
        this.showSnackbar(
          `Please select the new supervisor for ${this.myRequest.partnerName || "the exchange partner"}.`,
          "error",
        );
        return;
      }
      if (!this.form.date || this.form.date > this.today) {
        this.showSnackbar("Effective date cannot be in the future.", "error");
        return;
      }
      this.confirmDialog = true;
    },

    // Backend contract: POST /fhir/QuestionnaireResponse, routed via the
    // "hod-apply-staff-exchange-location" Questionnaire to
    // applyStaffExchangeLocationWorkflow.js, with this.fhir = {
    //   request: "<my own exchange request Basic id>",
    //   supervisor: "Practitioner/<id>" (new supervisor for MY staff),
    //   partnerSupervisor: "Practitioner/<id>" (new supervisor for the
    //     partner - only meaningful/required when sameDistrictHOD, since
    //     that's the only case where this one submission finalizes both
    //     sides at once),
    //   comments, date,
    // }
    async applyTransfer() {
      if (!this.form.supervisor.reference) {
        this.showSnackbar("Please select the new supervisor.", "error");
        this.confirmDialog = false;
        return;
      }
      if (this.sameDistrictHOD && !this.form.partnerSupervisor.reference) {
        this.showSnackbar(
          `Please select the new supervisor for ${this.myRequest.partnerName || "the exchange partner"}.`,
          "error",
        );
        this.confirmDialog = false;
        return;
      }
      if (!this.form.date || this.form.date > this.today) {
        this.showSnackbar("Effective date cannot be in the future.", "error");
        this.confirmDialog = false;
        return;
      }

      this.saving = true;
      try {
        this.fhir = {
          request: this.requestId,
          supervisor: this.form.supervisor.reference,
          comments: this.form.comments,
          date: this.form.date,
        };
        if (this.sameDistrictHOD) {
          this.fhir.partnerSupervisor = this.form.partnerSupervisor.reference;
        }
        this.afterSaveMessage = "Transfer applied successfully!";
        await this.processFHIR();
        this.confirmDialog = false;
        this.showSnackbar(this.afterSaveMessage, "success");
        setTimeout(() => this.goBack(), 300);
      } catch (err) {
        console.error("applyTransfer error:", err);
        this.showSnackbar("Failed to apply transfer. Please try again.", "error");
      } finally {
        this.saving = false;
      }
    },
  },
};
</script>

